            rollback.append({"hash": tx["hash"], "at": at, "reason": DEADLINE_EXPIRED})
        elif tx["sim"] == "revert":
            rollback.append({"hash": tx["hash"], "at": at, "reason": REVERT})
        elif packing == PACKING_NONCE:
            if at in keep_idx:
                survivors.append(tx)
            else:
                rollback.append({"hash": tx["hash"], "at": at, "reason": DEPENDENT_NONCE})
